inline bool VerifyClientMessageVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyClientMessage(
        verifier,  values->Get(i), types->GetEnum<ClientMessage>(i))) {
      return false;
    }
  }
  return true;
}

inline bool VerifyServerMessage(::flatbuffers::Verifier &verifier, const void *obj, ServerMessage type) {
  switch (type) {
    case ServerMessage_NONE: {
      return true;
    }
    case ServerMessage_State: {
      auto ptr = reinterpret_cast<const Furnace::State *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ServerMessage_Ack: {
      auto ptr = reinterpret_cast<const Furnace::Ack *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ServerMessage_HistoryResponse: {
      auto ptr = reinterpret_cast<const Furnace::HistoryResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ServerMessage_ProgramListResponse: {
      auto ptr = reinterpret_cast<const Furnace::ProgramListResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ServerMessage_ProgramContentResponse: {
      auto ptr = reinterpret_cast<const Furnace::ProgramContentResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ServerMessage_PreferencesResponse: {
      auto ptr = reinterpret_cast<const Furnace::PreferencesResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ServerMessage_DebugInfoResponse: {
      auto ptr = reinterpret_cast<const Furnace::DebugInfoResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ServerMessage_LogListResponse: {
      auto ptr = reinterpret_cast<const Furnace::LogListResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ServerMessage_LogContentResponse: {
      auto ptr = reinterpret_cast<const Furnace::LogContentResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ServerMessage_Error: {
      auto ptr = reinterpret_cast<const Furnace::Error *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyServerMessageVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyServerMessage(
        verifier,  values->Get(i), types->GetEnum<ServerMessage>(i))) {
      return false;
    }
  }
  return true;
}

inline const Furnace::ServerEnvelope *GetServerEnvelope(const void *buf) {
  return ::flatbuffers::GetRoot<Furnace::ServerEnvelope>(buf);
}

inline const Furnace::ServerEnvelope *GetSizePrefixedServerEnvelope(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<Furnace::ServerEnvelope>(buf);
}

inline bool VerifyServerEnvelopeBuffer(
    ::flatbuffers::Verifier &verifier) {
  return verifier.VerifyBuffer<Furnace::ServerEnvelope>(nullptr);
}

inline bool VerifySizePrefixedServerEnvelopeBuffer(
    ::flatbuffers::Verifier &verifier) {
  return verifier.VerifySizePrefixedBuffer<Furnace::ServerEnvelope>(nullptr);
}

inline void FinishServerEnvelopeBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<Furnace::ServerEnvelope> root) {
  fbb.Finish(root);
}

inline void FinishSizePrefixedServerEnvelopeBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<Furnace::ServerEnvelope> root) {
  fbb.FinishSizePrefixed(root);
}

